from pathlib import Path
import base64,json,os,re,subprocess
root=Path.home()/'ASTRA-Frontend-latest'
backend=Path.home()/'ASTRA-Backend-latest'
listeners=subprocess.check_output(['ss','-ltnp','sport = :5200'],text=True)
pids=set(re.findall(r'pid=(\d+)',listeners))
if len(pids)!=1:raise SystemExit('STOP: expected the running preview backend.')
proc=Path('/proc')/pids.pop()
if proc.stat().st_uid!=os.getuid() or (proc/'cwd').resolve()!=backend.resolve():raise SystemExit('STOP: unexpected preview owner or folder.')
env={os.fsdecode(k):os.fsdecode(v) for k,v in [p.split(b'=',1) for p in (proc/'environ').read_bytes().split(b'\0') if b'=' in p]}
if (env.get('DOTNET_ENVIRONMENT') or env.get('ASPNETCORE_ENVIRONMENT'))!='Development':raise SystemExit('STOP: only the Development preview will be updated.')
contents=json.loads(base64.b64decode(''))
original={root/path:(root/path).read_text(encoding='utf-8-sig') for path in contents}
component=original[root/'src/pages/ticket-qa-check.tsx']
if 'function TicketQaCheck(' not in component or '/qa-reviews' not in component:raise SystemExit('STOP: unexpected QA component version. No files changed.')
try:
    for path,text in contents.items():(root/path).write_text(text,encoding='utf-8')
    subprocess.run(['npm','run','build'],cwd=root,check=True)
except BaseException:
    for path,text in original.items():path.write_text(text,encoding='utf-8')
    raise
print('SUCCESS: Ubuntu QA now uses four rows of five stars and an overall percentage.',flush=True)
print('No backend restart or database changes were needed.',flush=True)
